var e={operations:{title:`إدارة العمليات`,description:`نبني منظومة تشغيلية منضبطة للصيدلية، بدءًا من إجراءات التشغيل القياسية والتحكم في المخزون وحتى تحسين المشتريات وتحليل هوامش الربح، لنحوّل العمل اليومي إلى نتائج مالية قابلة للقياس.`,points:[`إجراءات التشغيل القياسية (SOPs)`,`التحكم في المخزون وتقليل الأصناف الراكدة`,`تحسين المشتريات والتفاوض مع الموردين`,`تحليل هوامش الربح وتسعير المنتجات`]},marketing:{title:`التسويق والنمو`,description:`نصمّم وننفّذ استراتيجيات تسويق محلية للتجزئة تجذب العملاء الجدد وتحتفظ بالحاليين، مع تحسين ظهور الصيدلية على Google وبناء برامج ولاء فعّالة.`,points:[`التسويق المحلي للتجزئة`,`تحسين نشاط الصيدلية على Google`,`برامج الولاء والاحتفاظ بالعملاء`,`العروض الترويجية وإدارة الحملات`]},hr:{title:`الموارد البشرية`,description:`نبني فريقًا صيدلانيًا عالي الأداء من خلال التوظيف الصحيح والأوصاف الوظيفية الواضحة وأنظمة الحوافز والتدريب العملي المستمر.`,points:[`التوظيف والاختيار`,`الأوصاف الوظيفية ومؤشرات الأداء`,`أنظمة الحوافز والمكافآت`,`تدريب الموظفين وتطويرهم`]},quality:{title:`الجودة والتميّز`,description:`نضع معايير جودة واضحة وأطر مؤشرات أداء وتقارير تنفيذية، ونوحّد التنفيذ عبر الفروع لضمان تجربة متسقة للمرضى.`,points:[`معايير الجودة وضمانها`,`أطر مؤشرات الأداء (KPIs)`,`التقارير التنفيذية`,`توحيد المعايير عبر الفروع`]}};function t(t,n){if(n!==`ar`)return t;let r=e[t.id];return r?{...t,...r}:t}export{t};